#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MILL_USER="${MILL_USER:-millwright}"
DOMAIN="hooks.kirhgoff.me"
PEM_PATH="$HOME/.config/mill/mill-inspector.pem"

check_until() {
  local description="$1"
  shift
  until "$@" >/dev/null 2>&1; do
    warn "check failed: $description"
    confirm "Skip this check?" && return 0
    pause "Fix it, then press Enter to check again"
  done
  printf '  %s✓ %s%s\n' "$GREEN" "$description" "$RESET"
}

webhook_rejects_unsigned() {
  [[ "$(curl -s -o /dev/null -w '%{http_code}' -X POST "https://$DOMAIN/github")" == 401 ]]
}

domain_resolves() {
  [[ -n "$(dig +short "$DOMAIN")" ]]
}

telegram_token_works() {
  curl -fs "https://api.telegram.org/bot$1/getMe" | grep -q '"ok":true'
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="$HOME/.config/mill/mill.env"

banner "Robot mill setup"

stage "macOS user $MILL_USER"
say "Run this from your own account first. The farm runs as $MILL_USER, logged in behind your session."
step "System Settings → Users & Groups → Add User → name it $MILL_USER."
step "Make it an Administrator: Homebrew needs it to install tmux, gh and cloudflared."
step "Users & Groups → Automatically log in as → $MILL_USER (FileVault blocks this; leave it off for this Mac)."
step "Control Center → Fast User Switching → Show in Menu Bar, then switch to $MILL_USER and log in once."
check_until "macOS user $MILL_USER exists" dscl . -read "/Users/$MILL_USER"
if [[ "$(whoami)" != "$MILL_USER" ]]; then
  say "Now switch to $MILL_USER, open Terminal, clone this repo to ~/Projects/robot-mill and run:"
  say "  scripts/setup-wizard.sh"
  say "Stages 2-8 run as $MILL_USER."
  exit 0
fi

stage "GitHub machine user, SSH key and dotfiles access"
say "Create a GitHub account for the farm and let it clone your private dotfiles."
open_url "https://github.com/signup"
step "Sign up as $MILL_USER, or the nearest free name."
ask MILL_BOT_LOGIN "GitHub username you got:"
check_until "GitHub user $MILL_BOT_LOGIN exists" gh api "users/$MILL_BOT_LOGIN"
step "In Terminal as $MILL_USER, create a key: ssh-keygen -t ed25519 -N '' -f ~/.ssh/id_ed25519"
open_url "https://github.com/settings/ssh/new"
step "Add ~/.ssh/id_ed25519.pub twice: once as Authentication Key, once as Signing Key (pbcopy < ~/.ssh/id_ed25519.pub)."
step "Then: git config --global gpg.format ssh; git config --global user.signingkey ~/.ssh/id_ed25519.pub; git config --global commit.gpgsign true"
step "Run: gh auth login (GitHub.com, SSH, log in as $MILL_BOT_LOGIN)."
check_until "gh is logged in" gh auth status
say "From your own GitHub account, make the farm able to read dotfiles."
open_url "https://github.com/kirhgoff/dotfiles/settings/access"
step "Add people → $MILL_BOT_LOGIN → Read."
open_url "https://github.com/kirhgoff/dotfiles/invitations"
step "As $MILL_BOT_LOGIN, accept the invitation."
check_until "$MILL_BOT_LOGIN can read kirhgoff/dotfiles" gh api repos/kirhgoff/dotfiles --jq .permissions.pull

stage "Install the farm"
say "install.sh installs the tools, clones dotfiles, links skills, writes the tunnel config and LaunchAgents."
confirm "Run install.sh now?" && "$REPO/install.sh"
[[ "$MILL_BOT_LOGIN" == millwright ]] || write_env MILL_BOT_LOGIN "$MILL_BOT_LOGIN"

stage "GitHub App mill-inspector"
say "This App delivers webhooks for all your repos and posts the reviews."
WEBHOOK_SECRET="$(openssl rand -hex 32)"
write_env GITHUB_WEBHOOK_SECRET "$WEBHOOK_SECRET"
open_url "https://github.com/settings/apps/new"
step "GitHub App name: mill-inspector. Homepage URL: any."
step "Webhook URL: https://$DOMAIN/github"
step "Webhook secret: $WEBHOOK_SECRET"
step "Permissions: Pull requests write, Contents read, Metadata read."
step "Subscribe to: Pull request, Pull request review, Pull request review comment, Issue comment."
step "Create it, then Generate a private key and move it to $PEM_PATH"
step "Install App → your account → All repositories."
ask GITHUB_APP_ID "App ID (top of the App settings page):"
check_until "private key at $PEM_PATH" test -s "$PEM_PATH"
chmod 600 "$PEM_PATH"
write_env GITHUB_APP_ID "$GITHUB_APP_ID"
write_env GITHUB_APP_PRIVATE_KEY_PATH "$PEM_PATH"

stage "Cloudflare tunnel for $DOMAIN"
say "The tunnel is named mill; install.sh already wrote its config."
step "Log in: cloudflared tunnel login (pick the kirhgoff.me zone in the browser)."
step "Create it: cloudflared tunnel create mill"
step "Route DNS: cloudflared tunnel route dns mill $DOMAIN"
check_until "tunnel mill exists" cloudflared tunnel info mill
check_until "$DOMAIN resolves" domain_resolves

stage "Telegram and Linear keys"
say "Reuse the old bot: its token and chat id are in the copy you kept from peeper's ~/.envs/robot-mill/."
ask_secret TELEGRAM_BOT_TOKEN "Telegram bot token:"
check_until "Telegram accepts the token" telegram_token_works "$TELEGRAM_BOT_TOKEN"
ask TELEGRAM_CHAT_ID "Your Telegram chat id:"
open_url "https://linear.app/settings/account/security"
step "Create a personal API key named mill."
ask_secret LINEAR_API_KEY "Linear API key:"
open_url "https://linear.app/settings/api"
step "Webhooks → New webhook: URL https://$DOMAIN/linear, data change events: Issues."
step "Copy the signing secret Linear shows after saving."
ask_secret LINEAR_WEBHOOK_SECRET "Linear webhook signing secret:"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
write_env LINEAR_API_KEY "$LINEAR_API_KEY"
write_env LINEAR_WEBHOOK_SECRET "$LINEAR_WEBHOOK_SECRET"

stage "Log the agents in"
say "Each tool is logged in once, by hand, as $MILL_USER."
step "Run: claude   (finish the login, then exit)"
step "Run: codex login"
check_until "claude is logged in" claude auth status
check_until "codex is logged in" codex login status

stage "Start the farm and protect repos"
launchctl kickstart -k "gui/$(id -u)/me.kirhgoff.mill" || warn "couldn't restart the mill agent; run install.sh again"
launchctl kickstart -k "gui/$(id -u)/me.kirhgoff.mill-tunnel" || warn "couldn't restart the tunnel agent"
say "Give it a few seconds to start."
sleep 5
check_until "https://$DOMAIN/github answers 401 to an unsigned request" webhook_rejects_unsigned
say "Last step, from your own account (not $MILL_USER), in the repo checkout:"
say "  cd mill && bun run src/main.ts protect --all-linear"
note "It makes every Linear-mapped repo require 1 approval and invites $MILL_BOT_LOGIN as a collaborator."

finish
}

run_wizard "$@"; exit
